mapper.select:
WITH RECURSIVE space_tree(id,space_name) AS ( SELECT id,space_name FROM BBX_PARK_SPACE
sslc_code = #{sslcCode}
AND tenant_id = #{tenantId}
UNION ALL SELECT s.id,s.space_name FROM BBX_PARK_SPACE s INNER JOIN space_tree st ON s.parent_space_id = st.id ) SELECT TO_CHAR(TRUNC(r.record_time), 'MM-dd') as date, ROUND(AVG(r.online) * 100,2) as online_rate, ROUND(AVG(r."alarm") * 100,2) as alarm_rate FROM bbx_device_health_record r INNER JOIN space_tree st1 ON r.space_id = st1.id WHERE r.record_time >= SYSDATE - 30
AND r.tenant_id = #{tenantId}
GROUP BY r.record_time ORDER BY date
